    ORDER BY id ASC
  `);
  
  const results: MigrationRecord[] = [];
  while (stmt.step()) {
    const row = stmt.getAsObject() as unknown as MigrationRecord;
    results.push(row);
  }
  stmt.free();
  
  return results;
}

