    .split(';')
    .map(s => s.trim())
    .filter(s => s.length > 0);
  
  for (const stmt of statements) {
    db.run(stmt);
  }
  
  // Insert migration record
  db.run('INSERT INTO schema_migrations (name) VALUES (?)', [migration.name]);
  saveDatabase();
  
  console.log(`Applied migration: ${migration.name}`);
}

