  const db = openDatabase();
  
  // Split the rollback SQL into individual statements
  const statements = migration.down
    .split(';')
    .map(s => s.trim())
    .filter(s => s.length > 0);
  
  for (const stmt of statements) {
    db.run(stmt);
  }
  
  saveDatabase();
  console.log(`Rolled back migration: ${migration.name}`);
}

